text:
{{(() => {
  const ratings = [
    Rating51Copy.value,
    Rating52Copy.value,
    Rating53Copy.value,
    Rating54Copy.value,
    Rating55Copy.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0 || r === "");
  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: RISORSA IN GRADO DI LAVORARE IN AUTONOMIA IN UN TURNO A DUE";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" :
    (somma >= 20
      ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: RISORSA IN GRADO DI LAVORARE IN AUTONOMIA IN UN TURNO A DUE"
      : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: RISORSA IN GRADO DI LAVORARE IN AUTONOMIA IN UN TURNO A DUE");
})()
}}

